#!/usr/bin/env node
/*
  FRONTIER UI BINDINGS — Native widget FFI definitions
  Replaces: Capacitor WebView HTML/CSS rendering
*/

function generateUIBindings() {
  return `// frontier.ui — Native platform bindings (UIKit / Android Views)
// Generated by Lighthouse Frontier overhaul

module frontier.ui;

extern fn screen_new(title: &str) -> Screen;
extern fn screen_add_button(screen: Screen, id: &str, label: &str, action: &str);
extern fn screen_add_text_input(screen: Screen, id: &str, placeholder: &str);
extern fn screen_add_list(screen: Screen, id: &str, items: Vec<String>);
extern fn screen_add_text(screen: Screen, content: &str);
extern fn screen_render(screen: Screen);

type Screen = opaque;
`;
}

if (require.main === module) {
  const { writeFileSync, mkdirSync, existsSync } = require('fs');
  const { join } = require('path');
  const { GENERATED_DIR } = require('./lib/frontier-utils');
  if (!existsSync(GENERATED_DIR)) mkdirSync(GENERATED_DIR, { recursive: true });
  const out = join(GENERATED_DIR, 'frontier_ui_bindings.fr');
  writeFileSync(out, generateUIBindings());
  console.log(`✅ ${out}`);
}

module.exports = { generateUIBindings };
